<template>
  <v-container>
    <div class="text-center my-4">
      <v-menu>
        <template #activator="{ props: activatorProps }">
          <UiButton size="sm" v-bind="activatorProps">
            {{ $t("changeView") }}
          </UiButton>
        </template>
        <v-list>
          <v-list-item
            v-for="(color, name) in chat.personColorMap"
            :key="name"
            @click="changeEgoTo(name)"
          >
            <v-list-item-title :style="'color: ' + color">
              {{ name }}
            </v-list-item-title>
          </v-list-item>
        </v-list>
      </v-menu>
    </div>

    <!-- Chat -->
    <v-container id="chat" class="chat">
      <v-row
        v-for="(data, idx) in chat.chatObject.slice(
          startIdx,
          startIdx + offset,
        )"
        :key="idx"
        class="scroll-stop"
        no-gutters
      >
        <v-sheet
          :class="{
            myMessage: selectedEgo
              ? selectedEgo === data.author
              : !!chat.messagesPerPerson[0] &&
                chat.messagesPerPerson[0].name === data.author,
            system: chat.personColorMap[data.author] === undefined,
          }"
          class="pa-2 ma-2"
          color="rgb(38, 45, 49)"
          elevation="1"
          max-width="70%"
          rounded="lg"
        >
          <div
            :style="'color: ' + chat.personColorMap[data.author]"
            class="text-small font-weight-bold author text-left"
          >
            {{ data.author }}
          </div>

          <div v-if="data.media">
            <v-img contain width="100%" />
          </div>

          <Attachment
            v-if="data.attachment"
            :attachment-promise="_getAttachment(data.attachment.fileName)"
          >
          </Attachment>
          <div
            v-else
            class="text-white message"
            v-html="parseMessage(data.message)"
          ></div>

          <div
            class="text-caption text-right date pt-2"
            style="color: rgb(204, 204, 204)"
          >
            {{ _getDateString(data.date) }}
          </div>
        </v-sheet>
      </v-row>
      <v-row
        v-if="
          chat.chatObject.slice(startIdx + offset, startIdx + 2 * offset)
            .length > 0
        "
        class="my-8"
      >
        <UiButton class="ma-auto" @click="nextMessages">
          Load next {{ offset }} messages
        </UiButton>
      </v-row>
    </v-container>
  </v-container>
</template>

<script>
import { getDateString } from "~/utils/utils";
import { getAttachment } from "~/utils/attachments.ts";
import { analyticsChat } from "~/composables/useAnalytics";

export default {
  name: "Chat",
  props: ["chat", "attachments"],
  data() {
    return {
      startIdx: 0,
      selectedEgo: "",
      offset: 20,
    };
  },
  methods: {
    escapeHtml(text) {
      return text
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
    },
    parseMessage(message) {
      const validUrl = new RegExp(
        "(https?:\\/\\/)?" + // protocol
          "((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.)+[a-z]{2,}|" + // domain name
          "((\\d{1,3}\\.){3}\\d{1,3}))" + // OR ip (v4) address
          "(\\:\\d+)?(\\/[-a-z\\d%_.~+]*)*" + // port and path
          "(\\?[;&a-z\\d%_.~+=-]*)?" + // query string
          "(\\#[-a-z\\d_]*)?",
        "i",
      );

      // "<media omitted>", "<Medien ausgeschlossen>", ... — WhatsApp's own
      // marker for an attachment that was left out of the export. The whole
      // message is one angle-bracket tag, so it used to be dropped as unknown
      // HTML and left a bubble with nothing but a name and a time in it.
      const omitted = message.trim().match(/^<([^<>]+)>$/);
      if (omitted) {
        return (
          '<span class="omitted">📎 ' + this.escapeHtml(omitted[1]) + "</span>"
        );
      }

      const words = message.split(" ");
      let htmlMessage = "";
      words.forEach((word) => {
        const safeWord = this.escapeHtml(word);
        if (validUrl.test(word)) {
          // Always an absolute http(s) link: a bare "example.com" used to
          // become a link to a page on whatsanalyze.com, and anything else a
          // message can carry ("javascript:...") must never end up in an href.
          const href = /^https?:\/\//i.test(word)
            ? encodeURI(word)
            : "https://" + encodeURI(word.replace(/^[a-z]+:\/*/i, ""));
          htmlMessage +=
            '<a style="word-break: break-all" rel="noopener noreferrer" target="_blank" href="' +
            href +
            '">' +
            safeWord +
            "</a>" +
            " ";
        } else {
          htmlMessage += safeWord + " ";
        }
      });
      return htmlMessage;
    },
    changeEgoTo(name) {
      this.$emit("setEgo", name);
      this.selectedEgo = name;
      analyticsChat.participantChanged();
    },
    async _getAttachment(fileName) {
      return await getAttachment(fileName, this.attachments);
    },
    _getDateString(date) {
      return getDateString(date, true, this.$i18n.locale);
    },
    nextMessages() {
      this.startIdx += this.offset;
      const container = this.$el.querySelector("#chat");
      container.scrollTop = 0;
    },
  },
};
</script>

